SELECT DATE_FORMAT(stores.opened_date, 'yyyy-MM') AS opened_month, ROUND(STDDEV(store_sales.units), 2) AS stddev_units, ROUND(AVG(store_sales.units), 2) AS avg_units FROM store_sales LEFT JOIN stores ON store_sales.store_id = stores.id INNER JOIN products ON store_sales.product_id = products.id WHERE store_sales.product_id = 6 GROUP BY DATE_FORMAT(stores.opened_date, 'yyyy-MM') ORDER BY stddev_units DESC
